```json
{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name client_svc, s.service_name server_svc, s.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_med_ms, approx_quantile(s.duration,0.5)/1e6 server_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY 1,2,3",
          "claim": "Travel-service's outgoing seats/left_tickets client spans take a median 4.8 s, while seat-service's server spans take about 24 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name client_svc, s.service_name server_svc, s.span_name, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_med_ms, approx_quantile(s.duration,0.5)/1e6 server_med_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY 1,2,3",
          "claim": "In the normal period the same travel-to-seat call had a client median of about 27 ms, close to the server's 23 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name client_svc, c.attr_k8s_pod_name cpod, s.service_name server_svc, count(*) n, approx_quantile(c.duration,0.5)/1e6 client_med_ms, approx_quantile(s.duration,0.5)/1e6 server_med_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' GROUP BY 1,2,3",
          "claim": "Travel-plan-service calls the same seat endpoint in about 60 ms, so the seat connection and seat service are healthy; the delay is in travel-service's outgoing calls."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name client_svc, s.service_name server_svc, s.span_name, count(*) n, approx_quantile(s.duration,0.5)/1e6 callee_med_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY 1,2,3",
          "claim": "Route-plan's calls into travel-service show a 28.9 s p95 on the caller side, matching travel-service's own server-span tail, with the median fast."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Route-plan's calls to travel-service have a 28.9 s p95, the same as travel-service's server-side latency."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan show a 29.3 s p95, the same as route-plan's server-side latency."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-plan-service' GROUP BY 1,2",
          "claim": "Ui-dashboard's calls to travel-plan-service reach a 29.8 s p95, inheriting the delay from route-plan."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-ui-dashboard' AND s.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Ui-dashboard's direct calls to travel-service have a 31 s p95 and a 20 s caller-side p95."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-preserve-service' AND s.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Preserve-service's trip_detail calls to travel-service take about 11.6 s p95."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms, approx_quantile(c.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces s JOIN abnormal_traces c ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE s.attr_span_kind='Server' AND c.service_name='ts-ui-dashboard' AND s.service_name='ts-preserve-service' GROUP BY 1,2",
          "claim": "Ui-dashboard's calls to preserve-service take about 12 s p95, inheriting travel-service's delay."
        }
      ]
    }
  ]
}
